import {applyStoryEffects,rememberStory,storyCallback,finishStory} from './story.js?v=20261102-dream1';
function icon(name,extra=''){const paths={mission:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',guide:'<path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Z"/><path d="M12 6v14"/>',chronicle:'<path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/>',overlay:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',oxygen:'<path d="M12 3C9 8 5 12 5 16a7 7 0 0 0 14 0c0-4-4-8-7-13Z"/><path d="M8 16a4 4 0 0 0 4 4"/>',energy:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4a9 9 0 1 0 10 10Z"/>',crew:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5"/>'};return `<svg class="ui-icon ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.spark}</svg>`}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chapters=[['A signal in the silence','Aboard the Aurora, oxygen is falling. Beyond the observation deck, an unfamiliar signal pulses from a sealed corridor. Your crew has one decision to make.',['Repair life support','Investigate the signal','Send a distress call']],['The hidden passenger','The corridor reveals a stranded engineer and a damaged navigation core. A distant station flickers into view. The crew must decide who, or what, to trust.',['Help the engineer','Scan the navigation core','Head for the station']],['Through the debris','A storm of orbital debris blocks the route. The Aurora shudders as an old beacon broadcasts a safe passage - but its coordinates are incomplete.',['Reinforce the shields','Follow the beacon','Take the long route']],['The last transmission','The station answers. Its docking system is dark, and a rescue shuttle has only enough power for a single approach. Your earlier decisions have brought you here.',['Share emergency power','Attempt manual docking','Launch a rescue drone']],['A way home','The Aurora reaches the edge of the storm. A narrow jump window is opening. The crew looks to the community for one final decision.',['Bring everyone aboard','Chart an untested jump','Wait for the rescue fleet']]];
let view='mission',live=false,auth=false,config={},state,working=false;const overlay=new URLSearchParams(location.search).has('overlay'),token=new URLSearchParams(location.search).get('overlay');const overlayRevision='20261102-dream1';const key='streamquest.v1';let timer;let received=false,connection='Connecting to live session…';let animatedResult=null;
const initial=()=>({round:0,status:'ready',oxygen:72,energy:85,chaos:50,votes:{},history:[],events:[],remaining:45,deadline:null,version:0,scene:chapters[0][1],draft:null,narrator:'Prepared story',title:chapters[0][0],choices:chapters[0][2],winner:null,facts:{},memory:[],consequences:[],ending:null});
try{state=JSON.parse(localStorage.getItem(key))||initial()}catch{state=initial()}
const channel='BroadcastChannel'in window?new BroadcastChannel('streamquest'):null;
function save(){state.version++;localStorage.setItem(key,JSON.stringify(state));channel?.postMessage(state)}
channel?.addEventListener('message',e=>{if(!live&&(!overlay||token==='demo')){state=e.data;render()}});window.addEventListener('storage',e=>{if(!live&&(!overlay||token==='demo')&&e.key===key){state=JSON.parse(e.newValue)||initial();render()}});
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function counts(){let c=[0,0,0];Object.values(state.votes).forEach(v=>c[v]++);return c}
function localAction(action,data={}){if(action==='reset'){state=initial();return}if(action==='start'&&state.status==='ready')state.status='approved';else if(action==='open'&&state.status==='approved'){state.status='voting';state.deadline=Date.now()+state.remaining*1000}else if(action==='pause'&&state.status==='voting'){state.remaining=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));state.status='paused';state.deadline=null}else if(action==='resume'&&state.status==='paused'){state.status='voting';state.deadline=Date.now()+state.remaining*1000}else if(action==='vote'&&state.status==='voting'&&Date.now()<state.deadline){if(!data.user?.trim())throw Error('Enter a viewer name.');state.votes[data.user.trim()]=data.choice}else if(action==='close'&&state.status==='voting'){let c=counts(),max=Math.max(...c),w=c.indexOf(max);state.winner=w;const oldFacts=new Set(Object.keys(state.facts||{}));const effect=applyStoryEffects(state,w);rememberStory(state,w);state.result={id:state.version+1,choice:state.choices[w],winner:w,counts:c,total:c.reduce((a,b)=>a+b,0),tied:c.map((n,i)=>n===max?i:null).filter(i=>i!==null),resolution:!c.reduce((a,b)=>a+b,0)?'no_votes':c.filter(n=>n===max).length>1?'tie':'winner',effects:effect.effects,new_memory:state.memory.filter(m=>!oldFacts.has(m.id)),closed_at:Date.now(),reveal_until:Date.now()+7000};state.history.push({round:state.round+1,choice:state.choices[w],votes:c.reduce((a,b)=>a+b,0),winner:w,counts:c,...effect});state.status='pending';state.deadline=null;let next=state.round+1;state.draft=next<5?`${state.result.resolution==='no_votes'?'No votes were cast; default A was selected.':state.result.resolution==='tie'?'The tie was resolved by A/B/C order.':`Your community chose to ${state.choices[w].toLowerCase()}.`} ${chapters[next][1]} ${storyCallback(state)}`:finishStory(state,w)}
else if(action==='approve'&&state.status==='pending'){state.round++;state.scene=state.draft;state.draft=null;state.votes={};state.winner=null;state.remaining=45;if(state.round>=5){state.status='ended';state.title='The Aurora remembers'}else{state.status='approved';state.title=chapters[state.round][0];state.choices=chapters[state.round][2]}}else throw Error('This action is not available right now.');}
async function action(a,data={}){if(live&&!auth){$('#host-key')?.focus();toast('Enter your host key above to unlock the controls.');return}if(working)return;working=true;try{if(live){const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:a,version:state.version,...data})});const j=await r.json();if(!r.ok)throw Error(j.error||'Action failed');state=j}else{localAction(a,data);save()}render()}catch(e){toast(e.message)}finally{working=false}}
function button(label,a,disabled=false,primary=false){if(live&&!auth)disabled=true;return `<button data-action="${a}" ${disabled?'disabled':''} class="${primary?'primary':''}">${label}</button>`}
function nav(){return `<aside><div class="aside-label">YOUR WORKSPACE</div>${[['mission','◈','Mission control'],['guide','?','How to play'],['chronicle','≋','Story chronicle'],['overlay','▣','Stream overlay'],['settings','⚙','Connections']].map(([id,symbol,label])=>`<button class="nav ${view===id?'active':''}" data-view="${id}">${icon(id)}<span>${label}</span></button>`).join('')}<div class="aside-foot"><img class="moon-badge" src="assets/moon-badge.svg" alt="Pastel crescent moon"><span class="pill">SEASON 01</span><p><strong>The Aurora expedition</strong><br/>One ship. One community.<br/>Every choice matters.</p><span>Built with Codex</span></div></aside>`}

function nextStep(){
 if(live&&!auth)return `<section class="next-step"><div class="step-count">${icon('spark')}</div><div><div class="eyebrow">A PREVIEW OF YOUR CONTROL ROOM</div><h3>See the story before you sign in</h3><p>This is a sample adventure. Your actual progress and controls appear after you enter your host key above.</p></div><button class="small" data-view="guide">Learn how to play ↗</button></section>`;
 const info={ready:['01','Start your expedition','Click Launch adventure below to prepare the first chapter.'],approved:['02','Let your community choose',live?'Click Open voting. Viewers then send !a, !b or !c in your Twitch chat.':'Click Open voting, then use the chat simulator below to try a viewer vote.'],voting:['03','The crew is voting',live?'Watch real chat votes arrive. The timer closes voting, or you can close it early.':'Enter a viewer name and click !a, !b or !c in the simulator below.'],paused:['—','Voting is paused','Click Resume voting when you and your community are ready.'],pending:['04','Review the next chapter','Read the host review below. Approve it to show the next scene to your viewers.'],ended:['05','Your expedition is complete','Open Story chronicle to revisit your decisions, or start a new adventure.']}[state.status];
 return `<section class="next-step" aria-label="Your next step"><div class="step-count">${icon(state.status==='voting'?'crew':'spark')}</div><div><div class="eyebrow">YOUR NEXT STEP</div><h3>${info[1]}</h3><p>${info[2]}</p></div><button class="small" data-view="guide">See the full guide ↗</button></section>`
}
function guide(){return `<div class="top"><div><div class="eyebrow">CAPTAIN'S HANDBOOK</div><h1>A story you play together<span class="heading-dot">.</span></h1><p>You control the show. Twitch chat controls the decisions.</p></div><button class="primary" data-view="mission">Go to mission control ↗</button></div><section class="guide-intro"><div><span class="tag">THE IDEA IN 20 SECONDS</span><h2>Imagine your viewers<br/>are the crew of a spaceship.</h2><p>The ship has a problem. You offer three possible actions. Viewers vote in Twitch chat, the most popular action wins, and the story continues with that decision.</p></div><div class="guide-example"><span>YOUR TWITCH CHAT</span><p><b>space_explorer</b> !b</p><p><b>cosmic_cat</b> !a</p><p><b>lunar_crew</b> !b</p><div>CHOICE B WINS ↗<br/><strong>Investigate the signal</strong></div></div></section><div class="guide-roles"><div class="panel pad"><div class="eyebrow">YOU · THE STREAMER</div><h2>Host the adventure</h2><p>Read the scene aloud, open voting, and approve each new chapter. Your password and controls stay on your dashboard.</p></div><div class="panel pad"><div class="eyebrow">YOUR VIEWERS · THE CREW</div><h2>Vote in Twitch chat</h2><p>Viewers send <code>!a</code>, <code>!b</code> or <code>!c</code>. They do not need to log in to this dashboard or know your host key.</p></div><div class="panel pad"><div class="eyebrow">OBS · THE STREAM</div><h2>Show the adventure</h2><p>OBS is the broadcasting app. Its Browser Source shows the story overlay on your stream, so viewers can see the scene and votes.</p></div></div><section class="panel pad guide-flow"><h2>Your first adventure, step by step</h2>${[['Connect your channel','In the local app, open Connections → Connect Twitch and authorize the account whose chat you will use. For a practice run here, use the simulator instead.'],['Launch the adventure','Go to Mission control → Launch adventure. The first story scene is ready to read.'],['Open voting','Click Open voting. You have a 45-second round. On Twitch, viewers type !a, !b or !c. In practice mode, enter a name in the simulator and click a command.'],['Watch the winning choice','The timer closes the round automatically, or click Close & resolve. The winning action changes oxygen, energy and the community meter.'],['Approve the next chapter','Read the host review. With an AI key, the backend can draft new narrative; otherwise a prepared scene is used. Click Approve next chapter to show it. Repeat for five chapters.']].map(([title,body],i)=>`<div class="step"><i>${i+1}</i><div><h3>${title}</h3><p>${body}</p></div></div>`).join('')}</section><section class="mode-explainer"><div><h3>Online demo</h3><p>A safe practice space with simulated votes and a sample story. No Twitch credentials needed.</p></div><div><h3>Your local app</h3><p>Open <code>http://localhost:8080</code> while the Python server runs. This is where you connect real Twitch chat and AI.</p></div></section><div class="row"><button class="primary" data-view="mission">I'm ready — open mission control</button><button data-view="overlay">Set up OBS overlay</button></div>`}

function storyMemory(){if(!(state.memory||[]).length)return '';return `<section class="story-memory"><div class="eyebrow">${icon('chronicle')} YOUR CHOICES LIVE ON</div><div class="memory-items">${state.memory.map(m=>`<span title="${esc(m.description)}">${icon('spark')}${esc(m.title)}</span>`).join('')}</div>${state.status==='ended'&&state.ending?`<strong class="ending-badge">Ending: ${esc(state.ending.title)}</strong>`:''}</section>`}
function revealing(){return state.result&&Date.now()<state.result.reveal_until}
function resultCard(){const r=state.result;if(!revealing())return '';const animate=animatedResult!==r.id;animatedResult=r.id;return `<section style="${animate?'':'animation:none'}" class="result-card" role="status" aria-live="polite" data-result="${r.id}"><div class="eyebrow">CHOICE CONSEQUENCES · ${live&&token!=='demo'?'BACKEND RESULT':'SAMPLE RESULT'}</div><h2>${r.resolution==='no_votes'?'No votes · default A':r.resolution==='tie'?`Tie ${r.tied.map(i=>'ABC'[i]).join(' / ')} · first tied choice selected`:'Winning choice'}</h2><h3>${'ABC'[r.winner]} · ${esc(r.choice)}</h3><p>${r.counts.map((n,i)=>`${'ABC'[i]}: ${n}`).join(' · ')} · Total: ${r.total} votes</p><div class="result-effects">${Object.entries(r.effects).map(([k,v])=>`<strong>${esc(k)} ${v>=0?'+':''}${v}</strong>`).join('')}</div><div class="result-memory"><b>New story memory</b>${r.new_memory.length?r.new_memory.map(m=>`<p>${esc(m.title)} — ${esc(m.description)}</p>`).join(''):'<p>No new facts gained.</p>'}</div><small>Next scene requires host approval.</small></section>`}
function broadcast(){
 const badge=token!=='demo'?`${received?'LIVE MODE':'LIVE OVERLAY'} · ${esc(connection)} · ${overlayRevision}`:'SAMPLE PREVIEW · simulated votes · no Twitch connection';
 const top=`<div class="broadcast-mode"><span class="broadcast-brand">${icon('spark')} streamquest <em>ai</em></span><span class="broadcast-connection">${badge}</span></div>`;
 if(token!=='demo'&&!received)return `<main class="broadcast broadcast-waiting">${top}<section class="broadcast-welcome"><img src="assets/moon-badge.svg" alt=""><h1>Waiting for the Aurora</h1><p>${esc(connection)}</p></section></main>`;
 const c=counts(),total=c.reduce((a,b)=>a+b,0),sec=state.status==='voting'?Math.max(0,Math.ceil((state.deadline-Date.now())/1000)):0;
 const status=state.status==='voting'?'Voting open':state.status==='pending'?'Voting closed · awaiting host approval':state.status==='paused'?'Voting paused':state.status==='ended'?'Expedition complete':'Voting closed';
 const resources=`<div class="broadcast-resources"><span>${icon('oxygen')} Oxygen <b>${state.oxygen}%</b></span><span>${icon('energy')} Energy <b>${state.energy}%</b></span><span>${icon('spark')} Chaos <b>${state.chaos}%</b></span></div>`;
 return `<main class="broadcast ${revealing()?'broadcast-revealing':''}">${top}${revealing()?`<div class="broadcast-result-meta">CHAPTER ${Math.min(state.round+1,5)} / 5 ${resources}</div>${resultCard()}`:`<section class="broadcast-story"><div class="stars" aria-hidden="true"></div><div class="broadcast-planet" aria-hidden="true"></div><div class="eyebrow">THE AURORA EXPEDITION · CHAPTER ${Math.min(state.round+1,5)} / 5</div><h1>${esc(state.title)}</h1><p>${esc(state.scene)}</p></section><div class="broadcast-vote"><div class="broadcast-status"><strong id="clock">${state.status==='voting'?sec+'s':status}</strong>${state.status==='voting'?'<span>Vote in Twitch chat</span>':''}</div>${resources}</div><div class="broadcast-choices">${state.choices.map((t,i)=>{const percent=total?Math.round(c[i]/total*100):0;return `<div class="broadcast-choice"><div class="broadcast-choice-head"><span class="broadcast-command">!${'abc'[i]}</span><span class="broadcast-percent">${percent}%</span></div><b>${'ABC'[i]} · ${esc(t)}</b><span class="broadcast-count">${c[i]} ${c[i]===1?'vote':'votes'}</span><div class="broadcast-track" aria-hidden="true"><i style="width:${percent}%"></i></div></div>`}).join('')}</div>`}</main>`
}
// Keep the full scene in the OBS canvas, including longer provider-approved text.
function fitBroadcast(){
 const panel=document.querySelector('.broadcast'),text=document.querySelector('.broadcast-story p');
 if(!panel||typeof getComputedStyle!=='function')return;
 panel.style.width='';panel.style.height='';panel.style.transform='';
 if(text){
  text.style.fontSize='';
  let size=parseFloat(getComputedStyle(text).fontSize);
  while(panel.scrollHeight>window.innerHeight+1&&size>14){size=Math.max(14,size-1);text.style.fontSize=size+'px'}
 }
 // Fit the entire content, including results, without hiding text or choices.
 // Increasing the logical canvas before scaling also allows long lines to reflow.
 let scale=1;
 for(let i=0;i<8&&panel.scrollHeight>panel.clientHeight+1;i++){
  scale*=panel.clientHeight/(panel.scrollHeight+2);
  panel.style.width=(100/scale)+'%';panel.style.height=(window.innerHeight/scale)+'px';
  panel.style.transform=`scale(${scale})`;panel.style.transformOrigin='top left';
 }
}
window.addEventListener('resize',()=>{if(overlay)render()});
if(overlay&&document.fonts)document.fonts.ready.then(()=>{fitBroadcast()});
function mission(){let c=counts(),total=c.reduce((a,b)=>a+b,0),sec=state.status==='voting'?Math.max(0,Math.ceil((state.deadline-Date.now())/1000)):state.remaining;return `<div class="top"><div><div class="eyebrow">MISSION CONTROL / THE AURORA EXPEDITION</div><h1>A little wonder. A new world<span class="heading-dot">.</span></h1><p>You host the adventure. Your viewers decide what happens next.</p></div><span class="pill ${state.status==='voting'?'green':''}">${live&&!auth?'Host controls locked':state.status==='voting'?'● Voting open':state.status==='pending'?'Awaiting approval':state.status==='ended'?'Mission complete':'Host in control'}</span></div>${nextStep()}${resultCard()}<div class="grid"><section class="panel adventure-panel"><div class="panel-head"><h2><span class="live-dot"></span> ${live&&!auth?'Sample story · unlock host controls':live?'Your live story':'Practice story'}</h2><span class="muted">Chapter ${Math.min(state.round+1,5)} <span style="opacity:.4">/ 5</span></span></div><div class="hero"><div class="small-planet"></div><div class="spacecraft" aria-hidden="true"><svg viewBox="0 0 180 120" fill="none"><path d="M28 68L87 45L145 55L102 78L28 68Z" fill="#BCEEFF"/><path d="M87 45L101 17L117 51" fill="#DBD2FF"/><path d="M102 78L118 91L145 55" fill="#8B7BDD"/><path d="M28 68L73 84L102 78" fill="#6B73CE"/><path d="M48 61L20 52L68 50" fill="#AC9AEF"/><path d="M133 62L158 66L145 75L119 72" fill="#7ECDE6"/><path d="M72 80L34 99L63 74" fill="#C1B3FF"/><path d="M87 45L103 48L90 59L73 56Z" fill="#283A7C"/><path d="M32 70L2 81L33 75" fill="#FF9E9C"/><path d="M44 75L10 91L47 81" fill="#FFD09D"/></svg></div><div class="orbit-label">AURORA / EXPLORATION VESSEL<br/>LIVE FROM THE EDGE OF THE UNKNOWN</div><div class="stars"></div><div class="hero-content"><span class="tag">${state.status==='ended'?'EXPEDITION COMPLETE':'DEEP SPACE · SECTOR 07'}</span><h2>${esc(state.title)}</h2><p>${esc(state.scene)}</p></div></div><div class="chapter-path">${Array.from({length:5},(_,i)=>`<div class="chapter-node ${state.round===i?'current':state.round>i?'complete':''}"><span>${state.round>i?'✓':String(i+1).padStart(2,'0')}</span><small>${['The signal','Passenger','Debris field','Transmission','A way home'][i]}</small></div>`).join('')}</div>${storyMemory()}<div class="vote-area">${state.status!=='ended'?`<div class="vote-intro"><div><h3>What should the crew do?</h3><span class="muted" style="font-size:12px">Vote in chat with <code>!a</code>, <code>!b</code> or <code>!c</code></span></div><strong class="timer" id="clock">${String(sec).padStart(2,'0')}<small style="font-size:11px">s</small></strong></div><div class="choices">${state.choices.map((t,i)=>`<div class="choice ${state.winner===i?'winner':''}"><div class="letter">${'ABC'[i]}</div><div><b>${esc(t)}</b><small>${['Cooperate · protect the crew','Explore · embrace the unknown','Strategize · find another way'][i]}</small></div><div class="percent">${total?Math.round(c[i]/total*100):0}%<small>${c[i]} votes</small></div><div class="vote-track"><div class="vote-fill" style="width:${total?c[i]/total*100:0}%"></div></div></div>`).join('')}</div>`:`<h2>One community. Five decisions.</h2><p class="muted">Your expedition is saved in the story chronicle. Start a new adventure whenever your crew is ready.</p>`}
<div class="controls">${state.status==='ready'?button('Launch adventure','start',false,true):''}${state.status==='approved'?button('Open voting','open',false,true):''}${state.status==='voting'?button('Close & resolve','close',false,true)+button('Pause','pause'):''}${state.status==='paused'?button('Resume voting','resume',false,true):''}${state.status==='pending'?button(state.round===4?'Approve ending':'Approve next chapter','approve',false,true):''}${button('New adventure','confirm-reset')}</div>${state.draft?`<div class="notice"><strong>HOST REVIEW · ${esc(state.narrator)}</strong><p>${esc(state.draft)}</p>This draft will appear on stream only after your approval.${(state.consequences||[]).length?`<div class="consequence-list">${state.consequences.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}</div>`:''}${!live?`<div class="demo-controls"><div class="eyebrow">${icon('crew')} PRACTICE WITH A VIEWER VOTE</div><p class="muted" style="font-size:12px;margin:7px 0">Try a viewer vote. Reuse the same name to change their choice.</p><div class="row"><input id="viewer" aria-label="Viewer name" placeholder="Viewer name" value="${esc(sessionStorage.getItem('viewer')||'space_explorer')}">${[0,1,2].map(i=>`<button data-vote="${i}" ${state.status!=='voting'?'disabled':''}>!${'abc'[i]}</button>`).join('')}<span class="muted" style="font-size:11px">Real Twitch: Connections →</span></div></div>`:''}</div></section><div class="side"><section class="panel pad"><div class="eyebrow">${icon('spark')} SHIP STATUS</div><div class="stats" style="margin-top:16px"><div class="stat"><span>${icon('oxygen')} OXYGEN</span><strong style="color:var(--mint)">${state.oxygen}<small style="font-size:13px">%</small></strong><span>Life support</span><div class="resource-track"><i style="width:${state.oxygen}%"></i></div></div><div class="stat"><span>${icon('energy')} ENERGY</span><strong style="color:var(--violet)">${state.energy}<small style="font-size:13px">%</small></strong><span>Ship reserves</span><div class="resource-track energy"><i style="width:${state.energy}%"></i></div></div></div><div style="margin-top:22px"><h3>Community alignment</h3><div class="meter"><i class="needle" style="left:${state.chaos}%"></i></div><div class="ends"><span>COOPERATION</span><span>CHAOS</span></div><p class="muted" style="font-size:12px;margin-bottom:0">${state.chaos>60?'A daring crew, drawn to the unknown.':state.chaos<40?'Stronger together. Your crew comes first.':'A little courage. A little caution.'}</p></div></section><section class="panel pad"><div class="row" style="justify-content:space-between"><h3 style="margin:0">${icon('crew')} Crew activity</h3><span class="pill">${total} votes</span></div><div class="log"><div class="entry">${live&&!auth?'Your crew is waiting':live?esc(config.twitch||'Twitch not connected'):'Demo station online'}<span>${live&&!auth?'Unlock to view your live connection':live?'Backend-authoritative session':'Simulated viewers · no Twitch connection'}</span></div>${state.history.slice(-3).reverse().map(e=>`<div class="entry">${esc(e.choice)}<span>Chapter ${e.round} · ${e.votes} community votes</span></div>`).join('')}${!state.history.length?'<div class="entry">The story is yours to write.<span>Launch the adventure to get started.</span></div>':''}</div></section><section class="panel pad"><div class="eyebrow">READY FOR BROADCAST</div><h3 style="margin-top:12px">${icon('overlay')} Made for the big screen</h3><p class="muted" style="font-size:12px">A clean, read-only overlay for your OBS Browser Source.</p><button data-view="overlay" class="small">Set up stream overlay ↗</button></section></div></div>`}
function chronicle(){return `<div class="top"><div><div class="eyebrow">COMMUNITY MEMORY</div><h1>Every choice leaves a trace.</h1><p>Your expedition, one decision at a time.</p></div><button id="export" ${live&&!auth?'disabled':''}>Export chronicle ↓</button></div><div class="panel wide pad">${live&&!auth?'<div class="empty">Your real story history appears after you unlock. This page will record every winning community decision.</div>':state.history.length?state.history.map(e=>`<div class="step"><i>${e.round}</i><div><h3>${esc(e.choice)}</h3><p>${e.votes} votes · ${e.votes?'Community decision':'No votes: safe default A'}</p>${e.effects?`<p>${Object.entries(e.effects).map(([k,v])=>esc(k)+' '+(v>=0?'+':'')+v).join(' · ')}</p>`:''}${(e.callbacks||[]).map(x=>`<p class="history-callback">${esc(x)}</p>`).join('')}</div></div>`).join(''):'<div class="empty">Your chronicle starts with the first community decision.</div>'}</div>`}
function overlayURL(){return location.origin+location.pathname+'?overlay='+encodeURIComponent(live?config.overlay_token||'':'demo')}
function overlayView(){return `<div class="top"><div><div class="eyebrow">STREAM TOOLS</div><h1>A window into your universe.</h1><p>Keep your dashboard private. Put the adventure on stream.</p></div></div><div class="panel wide pad"><h2>OBS Browser Source</h2><div class="step"><i>1</i><div><h3>Add a Browser Source in OBS</h3><p>Set the Browser Source to 1000 × 550 or 1920 × 1080. The overlay fits both sizes.</p></div></div><div class="step"><i>2</i><div><h3>Paste your overlay URL</h3><p>${live&&!auth?'Your private overlay URL appears after you unlock the dashboard.':`<code>${esc(overlayURL())}</code>`}</p><div class="row">${live&&!auth?'<button data-unlock data-view="overlay" class="primary">Unlock to get overlay URL</button>':'<button id="copy-overlay" class="primary">Copy URL</button><button id="open-overlay">Preview overlay ↗</button>'}</div></div></div><div class="step"><i>3</i><div><h3>Launch and open voting</h3><p>Only approved scenes appear. ${live?'The backend synchronizes OBS independently.':'This demo syncs same-origin browser tabs. OBS requires the local backend; see Connections.'}</p></div></div></div>`}
function settings(){return `<div class="top"><div><div class="eyebrow">CONNECTIONS</div><h1>Assemble your control room.</h1><p>Bring Twitch chat and AI storytelling into the adventure.</p></div><span class="pill">${live?'Backend online':'Browser demo'}</span></div><div class="settings-grid wide"><section class="panel pad"><h2>Twitch chat</h2><p class="muted">${live&&!auth?'Connect your Twitch channel after unlocking host controls. You can explore all dashboard sections first.':live?esc(config.twitch||'Not connected. Authorize your broadcaster account to receive real chat votes.'):'The hosted demo uses simulated votes. Run the included Python backend locally to connect your real Twitch channel.'}</p>${live&&!auth?'<button data-unlock data-view="settings" class="primary">Enter host key to connect</button>':live?'<button id="connect-twitch" class="primary">Connect Twitch ↗</button>':'<code>python3 -m backend.server</code><p class="muted">Open http://localhost:8080. Configure Twitch credentials in your environment using the project README.</p>'}</section><section class="panel pad"><h2>AI storyteller</h2><p class="muted">${live&&!auth?'Your AI connection status is private. Unlock to see whether an AI provider is configured.':live?esc(config.ai?'AI provider configured. Generated scenes still require your approval.':'No AI key configured. Prepared fallback scenes are active.'):'Prepared story mode is active. AI generation is available in the local backend with STORY_API_KEY and STORY_MODEL.'}</p><span class="pill">${live&&config.ai?'AI available':'Prepared fallback'}</span></section><section class="panel pad"><h2>Session settings</h2><p class="muted">Space adventure · 5 chapters · 45-second rounds · one replaceable vote per viewer.</p><p class="muted">Ties use the first tied choice (A, then B, then C). No votes choose A. Votes are accepted only while voting is open.</p>${live&&!auth?'<p class="muted">You are browsing a sample session. Enter your host key above to manage your actual adventure.</p>':live?'<button id="logout">Log out of host controls</button>':'<p class="muted">Demo progress is stored in this browser. Use New adventure to clear the current mission.</p>'}</section></div>`}
function login(){return `<section class="welcome-unlock" aria-label="Host access"><div class="welcome-lock-icon">${icon('moon')}</div><div class="welcome-copy"><div class="eyebrow">WELCOME ABOARD</div><h2>Your adventure starts here.</h2><p>Explore the dashboard preview below. Enter your host key to unlock your real session and controls.</p></div><form id="login"><label for="host-key">Host key</label><div class="unlock-input-row"><input type="password" id="host-key" placeholder="Enter your host key" required autocomplete="current-password"><button class="primary">Unlock dashboard</button></div><span class="unlock-hint">Use the password you set when starting the server.</span><span id="login-error" role="alert"></span></form></section>`}

function render(){lastReveal=!!revealing();if(overlay){document.body.classList.add('overlay-mode');$('#app').innerHTML=broadcast();fitBroadcast();return}document.body.classList.toggle('overlay-mode',overlay);document.body.classList.toggle('host-locked',live&&!auth&&!overlay);$('#app').innerHTML=`<header><div class="brand"><span class="brand-icon">${icon('spark')}</span>streamquest<b> ai</b></div><div class="header-right"><span class="pill ${live?'green':''}">${live?auth?'● Host unlocked':'◉ Preview · browse all pages':'◉ Practice mode'}</span><button class="small" ${live&&!auth?'data-unlock':''} data-view="settings">${live&&!auth?'Unlock host controls':live?'Connections':'Set up Twitch'}</button><button class="small help-button" data-view="guide">How it works ↗</button></div></header><div class="shell">${nav()}<main>${live&&!auth&&!overlay?login()+(view==='guide'?guide():view==='chronicle'?chronicle():view==='overlay'?overlayView():view==='settings'?settings():mission()):view==='guide'?guide():view==='chronicle'?chronicle():view==='overlay'?overlayView():view==='settings'?settings():mission()}<footer><span>STREAMQUEST AI · BUILT WITH CODEX</span><span>${live?auth?'Local app · your private host dashboard':'Sample preview · host controls locked':'Practice mode · sample story · simulated viewers'}</span></footer></main></div>`;bind()}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(b.hasAttribute('data-unlock')){document.querySelector('.welcome-unlock')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});$('#host-key')?.focus();return}view=b.dataset.view;render();window.scrollTo({top:0,behavior:'instant'})});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='confirm-reset'){if(confirm('Start a new adventure? Current progress will be cleared.'))action('reset')}else action(b.dataset.action)});document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{let user=$('#viewer').value;sessionStorage.setItem('viewer',user);action('vote',{user,choice:Number(b.dataset.vote)})});if($('#copy-overlay'))$('#copy-overlay').onclick=async()=>{try{await navigator.clipboard.writeText(overlayURL());toast('Overlay URL copied')}catch{toast('Copy the displayed URL manually')}};if($('#open-overlay'))$('#open-overlay').onclick=()=>window.open(overlayURL(),'_blank','noopener');if($('#export'))$('#export').onclick=()=>{let a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify({title:'StreamQuest AI chronicle',...state},null,2)],{type:'application/json'}));a.href=u;a.download='streamquest-chronicle.json';a.click();URL.revokeObjectURL(u)};if($('#connect-twitch'))$('#connect-twitch').onclick=()=>location.href='/auth/twitch';if($('#logout'))$('#logout').onclick=async()=>{await fetch('/api/logout',{method:'POST'});auth=false;state=initial();config={};view='mission';render()};if($('#login'))$('#login').onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:$('#host-key').value})});if(r.ok){auth=true;view='mission';await refresh();render();toast('Welcome aboard — host controls unlocked.')}else{const error=$('#login-error');if(error)error.textContent='Host key was not accepted. Check your password and try again.';$('#host-key')?.focus()}};}
async function refresh(){
 if(live&&!auth&&!overlay)return;
 try{
  const r=await fetch('/api/state'+(overlay?'?overlay='+encodeURIComponent(token):''),{cache:'no-store'});
  if(r.ok){
   const j=await r.json(),changed=JSON.stringify(j)!==JSON.stringify(state),reconnected=!received||connection!=='Connected';
   received=true;connection='Connected';if(overlay&&token!=='demo')live=true;
   if(changed)state=j;if(changed||reconnected)render();
  }else if(overlay){received=false;connection='Access unavailable · check overlay URL';render()}
  if(auth&&!overlay){const r=await fetch('/api/config');if(r.ok){const next=await r.json();if(JSON.stringify(next)!==JSON.stringify(config)){config=next;render()}}}
 }catch{connection='Disconnected · last received state';if(overlay)render();else if(live)toast('Backend disconnected. Reconnecting…')}
}
async function boot(){if(overlay&&token==='demo'){live=false;render();return}try{const r=await fetch('/api/health');if(r.ok&&(await r.json()).service==='streamquest'){live=true;if(!overlay){const c=await fetch('/api/config');auth=c.ok;if(auth)config=await c.json();else state=initial()}await refresh()}}catch{}render();if(live||overlay)setInterval(refresh,800)}
let lastReveal=false;setInterval(()=>{const active=!!revealing();if(active!==lastReveal){lastReveal=active;render()}if(state.status==='voting'){let sec=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));if($('#clock'))$('#clock').innerHTML=String(sec).padStart(2,'0')+'<small style="font-size:11px">s</small>';if(sec===0&&!live&&!overlay)action('close')}},250);boot();
